def test_run_mode_starts_pytest_with_the_stage_marker_and_a_strict_env(monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]) -> None:
    """--run starts python -m pytest in the repository root and returns its exit code; the env forces STRICT_E2E_GATES=1 over the parent."""
    calls: list[tuple[list[str], dict]] = []
    def runner(argv, **kwargs): calls.append((argv, kwargs)); return subprocess.CompletedProcess(argv, 3)
    monkeypatch.setenv('STRICT_E2E_GATES', '0'); monkeypatch.setenv('RUN_MARKET_DATA_PROVIDER_E2E', 'parent'); monkeypatch.delenv('MARKET_DATA_E2E_DATE', raising=False)
    assert test_selection.main(['--stage', 'staging_core_e2e', '--run'], runner=runner) == 3
    ((argv, kwargs),) = calls; nodes, marker = matrix.stage_selection('staging_core_e2e')
    assert argv == [sys.executable, '-m', 'pytest', *nodes, '-v', '--tb=short', '-o', 'addopts=', '-m', marker]
    assert kwargs['cwd'] == test_selection.ROOT_DIR and kwargs['check'] is False
    assert kwargs['env']['STRICT_E2E_GATES'] == '1' and kwargs['env']['RUN_MARKET_DATA_PROVIDER_E2E'] == 'parent' and kwargs['env']['MARKET_DATA_E2E_DATE'] == '2024-06-03'
    calls.clear(); assert test_selection.main(['--touched-files', '--run'], runner=runner) == 0; assert 'no touched journey' in capsys.readouterr().out
    with pytest.raises(SystemExit) as excinfo: test_selection.main(['--stage', 'staging_core_e2e', '--run', '--shell'], runner=runner)
    assert excinfo.value.code == 2
    monkeypatch.setattr(matrix, 'staging_core_e2e_selection', lambda: ()); assert test_selection.main(['--stage', 'staging_core_e2e', '--run'], runner=runner) == 2; assert 'empty test tuple' in capsys.readouterr().err; assert calls == []
